/usr/bin/bash -lc "python - <<'PY'
import json
from pathlib import Path
pairs={'MSFT':'web-1d9ae59f9f','GOOGL':'web-c02d0f9a38','META':'web-9079358b91','AMZN':'web-04ebc18624','NVDA':'web-3c6489b589'}
rows=[]
for co,sid in pairs.items():
 data=json.loads((Path('sources')/(sid+'.txt')).read_text()); f=data['filings']['recent']
 for i,form in enumerate(f['form']):
  day=f['filingDate'][i]
  if form=='8-K' and '2026-09-21'<=day<='2026-10-12':
   r={'company':co,'source_index':sid,'date':day,'items':f.get('items',['']*len(f['form']))[i],'url':f\"https://www.sec.gov/Archives/edgar/data/{int(data['cik'])}/{f['accessionNumber'][i].replace('-','')}/{f['primaryDocument'][i]}\"}
   rows.append(r)
print(json.dumps(rows,indent=2))
Path('analysis/2026-10-12-slip-recent-filings.json').write_text(json.dumps(rows,indent=2)+'\\n')
PY"

